import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_min(torch::Tensor x, int64_t dim);
"""


_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cstdint>
#include <math_constants.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__device__ __forceinline__ float min_propagate_nan(float a, float b) {
    if (isnan(a)) {
        return a;
    }
    if (isnan(b)) {
        return b;
    }
    return b < a ? b : a;
}

__global__ void cute_min_kernel(
    const float* __restrict__ x,
    float* __restrict__ out,
    int B,
    int D1,
    int D2,
    int dim)
{
    auto gX = make_tensor(
        make_gmem_ptr(x),
        make_shape(B, D1, D2),
        make_stride(D1 * D2, D2, 1));

    extern __shared__ float shared_min[];
    int tid = threadIdx.x;
    int output_index = blockIdx.x;
    float value = CUDART_INF_F;
    if (dim == 0) {
        int output_count = D1 * D2;
        if (output_index >= output_count) {
            return;
        }
        int d1 = output_index / D2;
        int d2 = output_index % D2;
        for (int k = tid; k < B; k += blockDim.x) {
            value = min_propagate_nan(value, gX(k, d1, d2));
        }
    } else if (dim == 1) {
        int output_count = B * D2;
        if (output_index >= output_count) {
            return;
        }
        int batch = output_index / D2;
        int output_col = output_index % D2;
        for (int k = tid; k < D1; k += blockDim.x) {
            value = min_propagate_nan(value, gX(batch, k, output_col));
        }
    } else {
        int output_count = B * D1;
        if (output_index >= output_count) {
            return;
        }
        int batch = output_index / D1;
        int d1 = output_index % D1;
        const float* row = x + (batch * D1 + d1) * D2;
        if ((reinterpret_cast<uintptr_t>(row) & 15u) == 0u) {
            int vector_count = D2 >> 2;
            for (int k = tid; k < vector_count; k += blockDim.x) {
                float4 v = reinterpret_cast<const float4*>(row)[k];
                value = min_propagate_nan(value, v.x);
                value = min_propagate_nan(value, v.y);
                value = min_propagate_nan(value, v.z);
                value = min_propagate_nan(value, v.w);
            }
            int tail_start = vector_count << 2;
            if (tid < (D2 - tail_start)) {
                value = min_propagate_nan(value, row[tail_start + tid]);
            }
        } else {
            for (int k = tid; k < D2; k += blockDim.x) {
                value = min_propagate_nan(value, row[k]);
            }
        }
    }
    for (int offset = 16; offset > 0; offset >>= 1) {
        value = min_propagate_nan(
            value, __shfl_down_sync(0xffffffffu, value, offset));
    }
    int lane = tid & 31;
    int warp = tid >> 5;
    if (lane == 0) {
        shared_min[warp] = value;
    }
    __syncthreads();
    if (warp == 0) {
        value = (lane < (blockDim.x >> 5)) ? shared_min[lane] : CUDART_INF_F;
        for (int offset = 16; offset > 0; offset >>= 1) {
            value = min_propagate_nan(
                value, __shfl_down_sync(0xffffffffu, value, offset));
        }
        if (lane == 0) {
            out[output_index] = value;
        }
    }

}
torch::Tensor cute_min(torch::Tensor x, int64_t dim) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.dim() == 3, "x must be a 3D tensor");
    TORCH_CHECK(
        x.scalar_type() == at::kFloat,
        "cute_min currently supports float32 tensors only");

    if (dim < 0) {
        dim += 3;
    }
    TORCH_CHECK(dim >= 0 && dim < 3, "reduction dimension must be in [-3, 2]");

    auto x_contiguous = x.contiguous();

    int B = static_cast<int>(x_contiguous.size(0));
    int D1 = static_cast<int>(x_contiguous.size(1));
    int D2 = static_cast<int>(x_contiguous.size(2));

    torch::Tensor out;
    dim3 grid;
    dim3 block(256);
    size_t shared_bytes = 32 * sizeof(float);

    if (dim == 0) {
        out = torch::empty({D1, D2}, x_contiguous.options());
        grid = dim3(D1 * D2, 1, 1);
    } else if (dim == 1) {
        out = torch::empty({B, D2}, x_contiguous.options());
        grid = dim3(B * D2, 1, 1);
    } else {
        out = torch::empty({B, D1}, x_contiguous.options());
        grid = dim3(B * D1, 1, 1);
    }

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    cute_min_kernel<<<grid, block, shared_bytes, stream>>>(
        x_contiguous.data_ptr<float>(),
        out.data_ptr<float>(),
        B,
        D1,
        D2,
        static_cast<int>(dim));

    TORCH_CHECK(
        cudaGetLastError() == cudaSuccess,
        "CUTE min kernel launch failed");

    return out;
}
"""


_cute_ext = load_inline(
    name="cute_min_cute_ext",
    cpp_sources=_cpp_decl,
    cuda_sources=_cuda_src,
    functions=["cute_min"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim
        self._ext = _cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_min(x, self.dim)

